import os
from openpyxl import load_workbook

os.makedirs('/root/output', exist_ok=True)
wb = load_workbook('/root/data/workbook.xlsx')
print('Sheets:', wb.sheetnames)

task = wb['Task']
data = wb['Data']

cols = ['H','I','J','K','L']
years = {c: task[f'{c}10'].value for c in cols}
print('\nTask!H10:L10 year headers:')
for c,v in years.items():
    print(f'  {c}10 = {v!r}')

ranges = [(12,17),(19,24),(26,31)]
print('\nTask series codes in column D:')
for a,b in ranges:
    print(f'  D{a}:D{b}')
    for r in range(a,b+1):
        v = task[f'D{r}'].value
        print(f'    D{r} = {v!r}')

print('\nTask labels rows 35-40 (cols C-E):')
for r in range(35,41):
