    print(f'  row {r}: {row}')

print('\nTask labels rows 42-47 (cols C-E):')
for r in range(42,48):
    row = {c: task[f'{c}{r}'].value for c in ['C','D','E']}
    print(f'  row {r}: {row}')

print('\nTask labels row 50 (cols C-E):')
for r in [50]:
    row = {c: task[f'{c}{r}'].value for c in ['C','D','E']}
    print(f'  row {r}: {row}')

print('\nTask metric block headings around rows 11-12, 18-19, 25-26 (cols B-G):')
for r in [11,12,18,19,25,26]:
    row = {c: task[f'{c}{r}'].value for c in ['B','C','D','E','F','G']}
    print(f'  row {r}: {row}')

print('\nData sheet rows 21-38 snapshot (cols A-L):')
